import re
from functools import wraps

from lxml import etree
from paramiko import SSHClient, AutoAddPolicy
from six import StringIO, ensure_str
from robot.api import logger
from robot.utils.robottime import timestr_to_secs

from .exception import (PerformanceMonitorException, ScfException, NotNumericValueFound, NoScopeValueDeclared,
                        NoDnValueFound)


def assure_ssh_connection(func):
    """Wrapper function to reload ssh connection to BTS if needed

    | **Author:** Sebastian Burniak
    | **Maintainer:** sebastian.burniak@nokia.com
    | **Released with version:** 2.7.2
    """
    @wraps(func)
    def wrapped(pm_instance):
        try:
            return func(pm_instance)
        except Exception as e:
            logger.warn("Exception ocurred: {e}".format(e=e))
            logger.warn("Reload connection")
            pm_instance.teardown()
            pm_instance.setup()
            return func(pm_instance)

    return wrapped


class Scf(object):
    REPORTING_INTERVAL_PARAMETER = 'reportingIntervalPm'

    @classmethod
    def parse_scf_file(cls, scf_file):
        """
        Parse xml scf file
        :param scf_file: scf_file
        :return: Element tree object of scf file
        """
        return Scf(etree.parse(scf_file))

    def __init__(self, scf_tree):
        self.scf_tree = scf_tree
        self.namespace = 'raml21.xsd'

    def get_managed_objects_by_class_name(self, class_name):
        """
        Search scf for managed objects with specific class name.
        :param class_name: class name to find
        :return: etree.Element if one managedObject, list of  etree.Element if more
        """

        managed_objects = self.scf_tree.xpath('//ns:managedObject[@class="{}"]'.format(class_name),
                                              namespaces={'ns': self.namespace})
        if len(managed_objects) == 1:
            return managed_objects[0]
        else:
            return managed_objects

    def get_parameter_by_name(self, param):
        """
        Returns parameter value.
        :param param: parameter name to find in scf
        :return: scf parameter value
        """
        measurement = self.scf_tree.xpath('//ns:p[@name="{}"]'.format(param), namespaces={'ns': self.namespace})
        try:
            return measurement[0].text
        except IndexError:
            raise ScfException("Parameter {p} not found".format(p=param))


class PerformanceMonitor(object):
    PM_FILE_DIRECTORY = '/rom/uri/PERFMON_FILES'
    COUNTERS_FILE_PATTERN = {'xml': 'PM.BTS*.xml*',
                             'raw': 'PM.BTS*.raw*',
                             'wcdma_xml': 'PM.BTS*0000.ANY.xml*'}

    def __init__(self, ssh_connection_params, scf_path):
        self.ssh_connection_params = ssh_connection_params
        self.scf_path = scf_path
        self.scf = None
        self.pm_file = None
        self.ssh_client = None
        self.sftp_client = None

    def setup(self):
        """Create ssh connection with BTS."""
        self.ssh_client = self.connect_to_bts()
        self.sftp_client = self.ssh_client.open_sftp()
        self.load_scf()

    @assure_ssh_connection
    def read_pm_file_from_bts(self):
        """Parse PM counter file from BTS."""
        self.load_pm_file(self.get_newest_pm_file_path(self.COUNTERS_FILE_PATTERN['xml']))

    @assure_ssh_connection
    def read_pm_file_for_wcdma_from_bts(self):
        """Parse PM counter file from BTS."""
        self.load_pm_file(self.get_newest_pm_file_path(self.COUNTERS_FILE_PATTERN['wcdma_xml']))

    @assure_ssh_connection
    def read_raw_pm_file_from_bts(self):
        """Parse PM counter file from BTS."""
        self.load_pm_file(self.get_newest_pm_file_path(self.COUNTERS_FILE_PATTERN['raw']))

    def teardown(self):
        """Close connection with BTS"""
        self.sftp_client.close()
        self.ssh_client.close()

    def enabled_in_scf(self, measurement):
        """
        Returns True if measurement parameter exist in scf and has non-zero value, else False.
        :param measurement: Measurement scf parameter name.
        :return: True if parameter enabled, False otherwise
        """
        interval = self.get_measurement_interval(measurement)
        return interval not in ['0', 'disabled', None]

    def get_measurement_interval(self, measurement):
        """
        Gets parameter value from scf and converts it to seconds.
        :return: float if measurement enabled, None otherwise
        """
        scf_value = self.scf.get_parameter_by_name(measurement)
        return self._timestr_to_sec(scf_value)

    def get_reporting_interval(self):
        """
        Gets reporting interval from scf and converts it to seconds.
        :return: float if reporting interval set, None otherwise
        """
        scf_value = self.scf.get_parameter_by_name(self.scf.REPORTING_INTERVAL_PARAMETER)
        return self._timestr_to_sec(scf_value)

    @staticmethod
    def _timestr_to_sec(timestr):
        try:
            interval = timestr_to_secs(timestr)
        except ValueError:
            return None
        else:
            if interval > 0:
                return interval
            else:
                return None

    def connect_to_bts(self):
        """
        Establish ssh connection with BTS.
        :return: ssh connection handler
        """
        ssh_client = SSHClient()
        ssh_client.set_missing_host_key_policy(AutoAddPolicy())
        ssh_client.connect(**self.ssh_connection_params)
        return ssh_client

    def load_scf(self):
        """
        Parse scf from bts.
        # :param path: BTS path to scf
        """
        with open(self.scf_path, 'r') as scf:
            self.scf = Scf.parse_scf_file(scf)

    def load_pm_file(self, path):
        """
        Extract xz file and parse xml from output.
        :param path: path to xml.xz file on BTS
        """
        command = 'gunzip --stdout < {path}'.format(path=path)
        stdin, stdout, stderr = self.ssh_client.exec_command(command)
        xml = StringIO(ensure_str(stdout.read()))
        self.pm_file = etree.parse(xml)

    def dump_pm_to_file(self, path):
        """
        Write PM output to file.
        :param path: destination file path
        """
        if self.pm_file:
            self.pm_file.write(path, pretty_print=True)
        else:
            raise PerformanceMonitorException("PM report not loaded.")

    def get_newest_pm_file_path(self, file_pattern='PM.BTS*.xml*'):
        """
        Returns path to latest PM file
        :return: Path to PM file
        """
        raw_command = 'find {path} -name \'{pattern}\' | sort -n'
        command = raw_command.format(path=self.PM_FILE_DIRECTORY, pattern=file_pattern)
        stdin, stdout, stderr = self.ssh_client.exec_command(command)
        try:
            return ensure_str(stdout.read().splitlines()[-1])
        except IndexError:
            raise PerformanceMonitorException("Can't find PM file on BTS.")

    def compare_counters(self, required_counters, occurrence):
        """
        Returns required counters which number of occurrence is less than expected
        or required counters which don't exist.
        :param required_counters: Required measurement counters
        :param occurrence: Number of expected counters occurrence
        :return: required counters which have not been found
        """
        not_found_counters = list()
        found_counters = list()
        try:
            for required in required_counters:
                xml_element = self.pm_file.xpath('//{required}'.format(required=required))
                if not xml_element or (len(xml_element) < occurrence):
                    not_found_counters.append(required)
                else:
                    found_counters.append(required)
        except AttributeError:
            raise PerformanceMonitorException("PM file not loaded")
        logger.debug("Found counters: {}".format(found_counters))
        return not_found_counters

    def counter_value(self, dn, counter_id, start_time=None, interval=None):
        try:
            if start_time is not None and interval:
                pm_pattern = re.compile(r'^\d{4}-\d{2}-\d{2}\D\d{2}:' + re.escape(str(start_time)))
                xml_helper = etree.Element("root")
                for child in self.pm_file.getroot():
                    if pm_pattern.match(child.attrib['startTime']) and child.attrib['interval'] == str(interval):
                        xml_helper.append(child)
                all_objects = xml_helper.xpath('//*[MO/DN="{dn}" and NE-WBTS_1.0/{id}]'.format(dn=dn, id=counter_id))
            else:
                all_objects = self.pm_file.xpath('//*[MO/DN="{dn}" and NE-WBTS_1.0/{id}]'.format(dn=dn, id=counter_id))
            counter_value = self._get_counter_value(all_objects, counter_id)
        except AttributeError:
            raise PerformanceMonitorException('PM file not loaded')
        if str(counter_value) == "nan":
            raise NotNumericValueFound("NaN value found in counter file in {dn} ID {id}".format(dn=dn, id=counter_id))
        return self._get_counter_value(all_objects, counter_id)

    @staticmethod
    def _get_counter_value(all_objects, counter_id):
        all_ids = []
        for pmmoresult in all_objects:
            all_ids.append(pmmoresult.xpath("NE-WBTS_1.0/{counter_id}".format(counter_id=counter_id)))
        all_ids = [elt[0] for elt in all_ids]
        try:
            counter_value = float(all_ids[0].text if len(all_ids) == 1 else all_ids[-1].text)
        except IndexError:
            raise NoDnValueFound("No DN value found")
        except ValueError:
            raise NotNumericValueFound("Counter value cannot be changed to float value")
        return counter_value

    def counter_scope(self, value):
        m = re.match(r"(-?\d*\.?\d*)\s?\W?\s?(-?\d*\.?\d*)?", value)
        return self._check_scope_correctness(m.groups())

    @staticmethod
    def _check_scope_correctness(scope):
        try:
            if scope[1] == "":
                return float(scope[0]),
            elif scope[0] > scope[1]:
                return float(scope[1]), float(scope[0])
            else:
                return float(scope[0]), float(scope[1])
        except ValueError:
            raise NoScopeValueDeclared("No scope declared or invalid declaration")

    @staticmethod
    def _generate_verdict(status, counter_id, counter_value, raw_value):
        dictionary_to_return = {'verdict': status,
                                'data_list': "{counter_id:<10}\t{value:<7}\t{raw_value}\n".format(
                                    counter_id=counter_id, value=counter_value, raw_value=raw_value)}
        return dictionary_to_return

    @staticmethod
    def compare_values(scope, counter_value, raw_value, counter_id):
        is_equal = len(scope) == 1 and scope[0] == counter_value
        is_in_scope = len(scope) > 1 and scope[0] <= counter_value <= scope[1]
        if is_equal or is_in_scope:
            return PerformanceMonitor._generate_verdict("PASS", counter_id, counter_value, raw_value)
        else:
            return PerformanceMonitor._generate_verdict("FAIL", counter_id, counter_value, raw_value)
